-- Migration 009 : localisation GPS (V1.13) — recherche « autour de moi » dans un rayon de 0 à 200 km
--
-- Table commune : toutes les communes de France avec leur code postal et un point GPS.
--   Sources : liste officielle des communes (INSEE, paquet @etalab/decoupage-administratif, licence ouverte)
--             et coordonnées GeoNames (CC-BY 4.0, https://www.geonames.org).
--   precision_gps : « ville » = coordonnées de la commune ; « code_postal », « intercommunalite », « arrondissement »
--                   = petite commune absente de GeoNames, placée au centre des communes voisines (quelques km d'écart).
-- Chaque membre reçoit le point GPS de sa commune ; ses annonces sont placées à cet endroit.

CREATE TABLE IF NOT EXISTS commune (
  id            INT AUTO_INCREMENT PRIMARY KEY,
  code_insee    VARCHAR(5)   NOT NULL,
  nom           VARCHAR(80)  NOT NULL,
  nom_recherche VARCHAR(80)  NOT NULL,           -- en minuscules, sans accents ni tirets : « saint guilhem le desert »
  code_postal   CHAR(5)      NOT NULL,
  departement   VARCHAR(3)   NOT NULL,
  latitude      DECIMAL(8,5) NOT NULL,
  longitude     DECIMAL(8,5) NOT NULL,
  population    INT          NOT NULL DEFAULT 0,
  precision_gps VARCHAR(20)  NOT NULL,
  UNIQUE KEY commune_cp (code_insee, code_postal),  -- une seule ligne par commune et par code postal
  INDEX (code_postal),
  INDEX (nom_recherche),
  INDEX (latitude, longitude)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE utilisateur
  ADD COLUMN latitude  DECIMAL(8,5) NULL,
  ADD COLUMN longitude DECIMAL(8,5) NULL,
  ADD INDEX (latitude, longitude);


-- Les membres déjà inscrits : point GPS de leur commune (même code postal, nom identique si possible, sinon la plus peuplée)
UPDATE utilisateur u SET
  latitude  = (SELECT c.latitude  FROM commune c WHERE c.code_postal = u.code_postal ORDER BY (c.nom = u.ville) DESC, c.population DESC LIMIT 1),
  longitude = (SELECT c.longitude FROM commune c WHERE c.code_postal = u.code_postal ORDER BY (c.nom = u.ville) DESC, c.population DESC LIMIT 1);
